INSERT INTO [Comercial_PricingAnalisisIA] ([AnalisisIAID], [ProductoID], [CodigoProducto], [ServerID], [EmpresaID], [UnidadNegocioID], [TipoAnalisis], [ModeloIAUsado], [VersionModelo], [PromptResumen], [DatosEntradaJSON], [RespuestaIAJSON], [JustificacionIA], [ConfianzaIA], [RequiereRevisionHumana], [PrecioActual], [PrecioSugerido], [MargenActual], [MargenSugerido], [CompetidoresUsadosJSON], [FuentesUsadasJSON], [EstadoAnalisis], [UsuarioEjecucion], [FechaEjecucion], [FechaCreacion], [ListaCompetidoresID]) VALUES ('bf15ced0-54e1-48fe-8fab-186c2e891021', NULL, N'0000005008', '1b230a06-ffaf-4c70-bd27-b1be3579dea6', 1, 1, N'ANALISIS_PRODUCTO', N'openai', N'gpt-5.2', N'Análisis de producto (C) Arrachera Lorenza de kg', N'{"producto": {"existe": true, "codigo": "0000005008", "nombre": "(C) Arrachera Lorenza de kg", "familia": "CARNES Y AVES", "subfamilia": null, "costo": 0.3635, "fuente_costo": "CostoInsumo", "precio_actual": -1.0, "margen_actual": null}, "unidad": {"existe": true, "nombre_comercial": "Origen Unión Gastronómica del Fuego", "concepto": null, "tipo_restaurante": "fine_dining", "segmento_precio": "PREMIUM", "ciudad": "Mérida", "estado": "Yucatán", "ticket_promedio_objetivo": null, "rango_precio_objetivo": null}, "competidores": [{"nombre": "La Habichuela", "tipo": "fine_dining", "segmento": "PREMIUM", "es_directo": true, "es_aspiracional": false, "items": [{"producto": "Lechón al Horno", "categoria": "Carnes", "precio": 380.0, "confianza": "ALTA"}, {"producto": "Sopa de Lima", "categoria": "Entradas", "precio": 150.0, "confianza": "ALTA"}, {"producto": "Cochinita Pibil", "categoria": "Especialidades Yucatecas", "precio": 220.0, "confianza": "ALTA"}]}], "benchmark": null, "precio_base_calculado": {"precio_sugerido": 0, "margen_objetivo": 0.35, "estado": "CALCULADO"}, "confianza_calculada": "MEDIA"}', N'{"justificacion": "El costo cargado ($0.36) es atípicamente bajo para una arrachera por kg y el precio actual está en -$1.00, lo que indica un error de captura/unidad y hace inviable calcular un precio comercial confiable. Para un restaurante fine dining premium en Mérida, el precio debe reflejar calidad del corte, merma, preparación y experiencia; por ello se requiere validar primero el costo real (por kg) para asegurar un margen objetivo de 35% sin distorsionar el menú.", "posicionamiento": "No hay benchmarks de precios contra competencia, por lo que no es posible confirmar si el precio quedaría alineado al segmento premium frente a La Habichuela u otros referentes locales. Con confianza de datos media y sin comparables, el riesgo de quedar fuera de mercado (muy bajo o muy alto) es elevado.", "recomendacion": "REQUIERE_MAS_DATOS", "precio_ajustado_sugerido": null, "observaciones": "Acciones sugeridas: (1) validar unidad del costo (¿$0.36 por gramo/porción vs por kg?) y su fuente; (2) corregir el precio actual negativo; (3) definir rendimiento/merma y gramaje de venta si no se vende realmente por kg; (4) capturar al menos 3-5 precios de arrachera/cortes equivalentes en competidores premium de Mérida para ajustar el precio final."}', N'El costo cargado ($0.36) es atípicamente bajo para una arrachera por kg y el precio actual está en -$1.00, lo que indica un error de captura/unidad y hace inviable calcular un precio comercial confiable. Para un restaurante fine dining premium en Mérida, el precio debe reflejar calidad del corte, merma, preparación y experiencia; por ello se requiere validar primero el costo real (por kg) para asegurar un margen objetivo de 35% sin distorsionar el menú.', N'MEDIA', 1, -1.00, NULL, NULL, NULL, N'["La Habichuela"]', N'["EDARSAHUB_SQL", "Sync_Productos", "Comercial_Competidores"]', N'REQUIERE_REVISION', N'admin@edarsa.com', N'2026-05-24T23:41:28.463333', N'2026-05-24T23:41:28.463333', NULL);
